import {money,intrinsic,strategies} from './pricing.js';import {buyingPower,committed,record} from './accounting.js';
export function preview(a,strategy,qty,ticker,expiration,low,high,getQuote){if(!strategies[strategy]||!Number.isInteger(qty)||qty<1||qty>100||!Number.isFinite(low)||low<=0||!Number.isFinite(high)||high<=low)throw Error('Check quantity and strikes (upper strike must exceed lower)');const legs=strategies[strategy].map(([type,side,upper])=>{const strike=upper?high:low,q=getQuote(type,strike);if(!q||![q.bid,q.ask].every(Number.isFinite)||q.bid<0||q.ask<q.bid)throw Error('Invalid or missing quote');return {type,side,strike,bid:q.bid,ask:q.ask}});const debit=money(legs.reduce((v,l)=>v+l.side*(l.side>0?l.ask:l.bid)*100*qty,0));const collateral=strategy==='Cash-secured put'?low*100*qty:strategy.includes('credit spread')?(high-low)*100*qty:0;if(strategy.includes('debit spread')&&(debit<0||debit>(high-low)*100*qty)||strategy.includes('credit spread')&&(debit>0||-debit>(high-low)*100*qty))throw Error('Quotes imply an invalid vertical price');if(strategy==='Covered call'&&(a.stocks[ticker]?.qty||0)-committed(a,ticker)<qty*100)throw Error('Buy 100 uncommitted shares per covered call first');if(buyingPower(a)-debit-collateral<0)throw Error('Insufficient buying power');return {strategy,qty,ticker,expiration,legs,debit,collateral,after:money(buyingPower(a)-debit-collateral)}}
export function execute(a,p,id){if(!id||a.executed.includes(id))throw Error('Order already executed');if(buyingPower(a)-p.debit-p.collateral<0)throw Error('Insufficient buying power');if(p.strategy==='Covered call'&&(a.stocks[p.ticker]?.qty||0)-committed(a,p.ticker)<p.qty*100)throw Error('Shares already reserved');a.cash=money(a.cash-p.debit);a.positions.push({...structuredClone(p),id});a.executed.push(id);record(a,'Open '+p.strategy,-p.debit,id);return id}
export function close(a,id,getQuote,settlement){const p=a.positions.find(p=>p.id===id);if(!p)throw Error('Position already closed');const credit=money(p.legs.reduce((n,l)=>{const q=settlement===undefined?getQuote(l.type,l.strike,p):null;if(q&&(!Number.isFinite(q.bid)||!Number.isFinite(q.ask)||q.bid<0||q.ask<q.bid))throw Error('Invalid close quote');return n+l.side*(q?(l.side>0?q.bid:q.ask):intrinsic(l.type,settlement,l.strike))*100*p.qty},0));if(settlement!==undefined&&p.strategy==='Covered call'){const shares=p.qty*100,held=a.stocks[p.ticker];a.cash=money(a.cash+shares*settlement);a.realized=money(a.realized+shares*(settlement-held.basis));held.qty-=shares;record(a,'Educational expiry sale of covered shares',shares*settlement)}if(a.cash+credit<a.positions.filter(x=>x.id!==id).reduce((n,x)=>n+x.collateral,0))throw Error('Closing needs more available cash. Add fictional funding before closing this covered call; its shares remain reserved.');a.cash=money(a.cash+credit);a.realized=money(a.realized+credit-p.debit);a.positions=a.positions.filter(p=>p.id!==id);record(a,(settlement===undefined?'Close ':'Cash-settle ')+p.strategy,credit);return money(credit-p.debit)}
export function stock(a,ticker,qty,price){if(!Number.isInteger(qty)||!qty||!Number.isFinite(price)||price<=0)throw Error('Enter a nonzero whole share quantity');const old=a.stocks[ticker]||{qty:0,basis:0};if(qty<0&&old.qty+qty<committed(a,ticker))throw Error('Cannot sell unowned or reserved shares');if(qty>0&&buyingPower(a)<money(qty*price))throw Error('Insufficient buying power');const basis=qty>0?(old.basis*old.qty+qty*price)/(old.qty+qty):old.basis;a.cash=money(a.cash-qty*price);if(qty<0)a.realized=money(a.realized-qty*(price-old.basis));a.stocks[ticker]={qty:old.qty+qty,basis};record(a,`${qty>0?'Buy':'Sell'} ${Math.abs(qty)} ${ticker} shares`,-qty*price)}

